def-hyp(
    Type.annotation(@A, Set(T@Set.ctxt.T)),
    Topology.connected(A),
    Logic.neg(
        Logic.exists-typed(
            @U,
            Set(T@Set.ctxt.T),
            Logic.exists-typed(
                @V,
                Set(T@Set.ctxt.T),
                Logic.and(
                    Logic.and(Set.mem(U, τ@Topology.ctxt.tau), Set.mem(V, τ@Topology.ctxt.tau)),
                    Logic.and(
                        Logic.and(Set.subset(U, A), Set.subset(V, A)),
                        Logic.and(
                            Logic.and(Logic.neg(Set.mem(U, Set.emptyset[slim])), Logic.neg(Set.mem(V, Set.emptyset[slim]))),
                            Logic.and(Eq(Set.inter(U, V), Set.emptyset[slim]), Eq(A, Set.union(U, V)))
                        )
                    )
                )
            )
        )
    )
)
